"""Best-effort process RAM and CUDA memory profiling that never gates inference."""

from __future__ import annotations

from dataclasses import dataclass
import os
from threading import Event, Thread


def process_rss_mb() -> float | None:
    try:
        import psutil

        return psutil.Process(os.getpid()).memory_info().rss / (1024 * 1024)
    except Exception:
        return None


def nvidia_process_vram_mb() -> float | None:
    try:
        import subprocess

        run = subprocess.run(
            [
                "nvidia-smi",
                "--query-compute-apps=pid,used_memory",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            timeout=5,
            check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        if run.returncode != 0:
            return None
        for line in run.stdout.splitlines():
            pid, separator, memory = line.partition(",")
            if separator and pid.strip() == str(os.getpid()) and memory.strip().isdigit():
                return float(memory.strip())
    except Exception:
        pass
    return None


def _torch_memory() -> tuple[float | None, float | None, float | None]:
    try:
        import torch

        if not torch.cuda.is_available():
            return None, None, None
        scale = 1024 * 1024
        return (
            torch.cuda.memory_allocated() / scale,
            torch.cuda.memory_reserved() / scale,
            torch.cuda.max_memory_allocated() / scale,
        )
    except Exception:
        return None, None, None


@dataclass(frozen=True)
class ResourceMetrics:
    rss_before_mb: float | None
    rss_after_mb: float | None
    peak_rss_mb: float | None
    torch_cuda_allocated_mb: float | None
    torch_cuda_reserved_mb: float | None
    torch_cuda_peak_allocated_mb: float | None
    nvidia_smi_process_vram_mb: float | None

    def to_dict(self) -> dict:
        return vars(self).copy()


class ResourceMonitor:
    def __init__(self, interval_seconds: float = 0.02):
        self.interval_seconds = interval_seconds
        self._stop = Event()
        self._thread = None
        self._rss_before = None
        self._peak = None
        self.metrics = ResourceMetrics(None, None, None, None, None, None, None)

    def __enter__(self):
        self._rss_before = process_rss_mb()
        self._peak = self._rss_before
        try:
            import torch

            if torch.cuda.is_available():
                torch.cuda.reset_peak_memory_stats()
        except Exception:
            pass

        def sample():
            while not self._stop.wait(self.interval_seconds):
                value = process_rss_mb()
                if value is not None and (self._peak is None or value > self._peak):
                    self._peak = value

        self._thread = Thread(target=sample, name="virvision-resource-monitor", daemon=True)
        self._thread.start()
        return self

    def __exit__(self, exc_type, exc, traceback):
        self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=1)
        after = process_rss_mb()
        if after is not None and (self._peak is None or after > self._peak):
            self._peak = after
        allocated, reserved, peak_allocated = _torch_memory()
        self.metrics = ResourceMetrics(
            self._rss_before,
            after,
            self._peak,
            allocated,
            reserved,
            peak_allocated,
            nvidia_process_vram_mb(),
        )
